"""ИИкузница. Первый прогон. Python 3.9+. Без установки пакетов."""
import argparse, base64, collections, csv, datetime, hashlib, json, os, pathlib, re, sys, time, urllib.request, urllib.error, zlib

MODELS = ['qwen/qwen3-14b','google/gemma-4-26b-a4b-it','qwen/qwen3.5-122b-a10b']
URL = 'https://openrouter.ai/api/v1/chat/completions'
DATA = json.loads(zlib.decompress(base64.b64decode('')))
def parse_message(value):
    raw=value.strip()
    if raw.startswith('```') and raw.endswith('```'):
        raw=re.sub(r'^\x60{3}(?:json)?\s*','',raw,flags=re.I)[:-3].strip()
    try:
        obj=json.loads(raw)
        return obj if isinstance(obj,dict) else {}
    except ValueError: return {}
def request_body(case,model):
    user=json.dumps({'question':case['question'],'sources':case['sources']},ensure_ascii=False)
    return {'model':model,'messages':[{'role':'system','content':DATA['system']},{'role':'user','content':user}],'temperature':0,'max_tokens':1536,'stream':True,'stream_options':{'include_usage':True}}
def run_one(case,model):
    body=request_body(case,model)
    headers={'Content-Type':'application/json','Accept':'text/event-stream'}
    key=os.environ.get('OPENROUTER_API_KEY')
    if key: headers['Authorization']='Bearer '+key
    req=urllib.request.Request(URL,data=json.dumps(body,ensure_ascii=False).encode(),headers=headers)
    start=time.monotonic()
    row={'id':case['id'],'model':model,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'ok':False,
         'text':'','ttft_s':None,'usage':{},'provider':None,'served_model':None,'completion_id':None,'finish':None}
    try:
        with urllib.request.urlopen(req,timeout=150) as response:
            row['http']=response.status
            if 'event-stream' not in response.headers.get('Content-Type','').lower():
                raise ValueError('Expected SSE, got '+str(response.headers.get('Content-Type')))
            completed=False
            for line in response:
                if not line.startswith(b'data:'): continue
                frame=line[5:].strip()
                if frame==b'[DONE]': completed=True; break
                obj=json.loads(frame)
                if obj.get('error'):
                    row['stream_error_code']=obj['error'].get('code');raise ValueError('OpenRouter stream error')
                for out,k in [('completion_id','id'),('served_model','model'),('provider','provider')]:
                    if obj.get(k):row[out]=obj[k]
                if obj.get('usage'):row['usage']=obj['usage']
                for choice in obj.get('choices') or []:
                    part=(choice.get('delta') or {}).get('content')
                    if isinstance(part,str) and part:
                        if row['ttft_s'] is None and part.strip():row['ttft_s']=round(time.monotonic()-start,3)
                        row['text']+=part
                    if choice.get('finish_reason'):row['finish']=choice['finish_reason']
            row['ok']=bool(row['text'].strip() and completed and row['finish'] not in ('error','length','content_filter'))
            if not row['ok']:row['error']='empty, truncated, or incomplete stream'
    except urllib.error.HTTPError as exc:
        row['http']=exc.code
        try:
            err=json.loads(exc.read()).get('error',{});msg=str(err.get('message',''))
        except Exception:msg='HTTP error'
        row['error']=re.sub(r'sk-[\w\-]+','[скрыто]',msg)[:320]
    except (OSError,ValueError) as exc:row['error']=type(exc).__name__+': '+str(exc)[:240]
    row['latency_s']=round(time.monotonic()-start,3)
    return row
def scores(rows,gold):
    for r in rows:
        obj=parse_message(r['text']); g=gold[r['id']]
        citations={(x.get('doc'),str(x.get('ref','')).strip('.')) for x in obj.get('sources',[]) if isinstance(x,dict)} if isinstance(obj.get('sources'),list) else set()
        expected={(x['doc'],x['ref']) for x in g['evidence']}
        yield {'model':r['model'],'id':r['id'],'http':r.get('http'),'complete':r['ok'],'expected_action':g['expected_action'],'actual_action':obj.get('action'),
               'action_ok':bool(r['ok'] and obj.get('action')==g['expected_action']),
               'cites_expected_ref':bool(citations&expected) if g['expected_action']=='answer' else None,
               'ttft_s':r['ttft_s'],'latency_s':r['latency_s'],'input_tokens':r['usage'].get('prompt_tokens'),
               'output_tokens':r['usage'].get('completion_tokens'),'cost_usd_openrouter':r['usage'].get('cost')}
def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');parser.add_argument('--out',default='iikuznitsa_run12');args=parser.parse_args()
    cases=DATA['cases'];gold={r['id']:r for r in DATA['gold']}
    assert len(cases)==len(gold)==12 and all(set(c)=={'id','question','sources'} and c['id'] in gold for c in cases)
    if args.check:
        print('OK: 12 inputs, 3 models, gold is not sent.');return
    dest=pathlib.Path(args.out);dest.mkdir(exist_ok=True,parents=True)
    log=dest/'attempts.jsonl'
    latest={}
    if log.exists():
        for line in log.read_text().splitlines():
            if line.strip():
                r=json.loads(line);latest[(r['id'],r['model'])]=r
    stop=False;skip=set()
    for case in cases:
        for model in MODELS:
            previous=latest.get((case['id'],model),{})
            if previous.get('ok') or model in skip:continue
            r=run_one(case,model);latest[(r['id'],model)]=r
            with log.open('a',encoding='utf-8') as f:f.write(json.dumps(r,ensure_ascii=False)+'\n')
            print(case['id'],model,r.get('http'),r['ok'],r['latency_s'],r.get('error',''),flush=True)
            if r.get('http') in (401,402):stop=True;break
            if r.get('http') in (400,403,404):skip.add(model)
            if r.get('http')==429:time.sleep(3)
        if stop:break
    final=list(scores(latest.values(),gold))
    if final:
        with (dest/'scores.csv').open('w',newline='',encoding='utf-8-sig') as f:
            out=csv.DictWriter(f,fieldnames=list(final[0]));out.writeheader();out.writerows(final)
    n=sum(r['ok'] for r in latest.values());print('Completed',n,'of 36')
    if n!=36:sys.exit(2)
if __name__=='__main__':main()
